  (99, 'PP', '11', 2019, 'Peraturan Pemerintah Nomor 11 Tahun 2019 tentang Perubahan Kedua atas Peraturan Pemerintah Nomor 43 Tahun 2014 tentang Peraturan Pelaksanaan Undang-Undang Nomor 6 Tahun 2014 tentang Desa', 'berlaku', 'Mengubah PP No. 43/2014 dan PP No. 47/2015; Sebagian digantikan oleh PP No. 16/2026', '{}', 'Nasional', 'Otonomi Daerah', 'https://peraturan.bpk.go.id/Details/102675/pp-no-11-tahun-2019', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (100, 'PP', '72', 2019, 'Peraturan Pemerintah Nomor 72 Tahun 2019 tentang Perubahan atas Peraturan Pemerintah Nomor 18 Tahun 2016 tentang Perangkat Daerah', 'berlaku', 'Mengubah PP No. 18/2016; Memperkuat kedudukan Inspektorat Daerah dan mengatur Rumah Sakit Daerah', '{}', 'Nasional', 'Otonomi Daerah', 'https://peraturan.bpk.go.id/Details/122033/pp-no-72-tahun-2019', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (101, 'UU', '2', 2017, 'Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi', 'berlaku', 'Diubah dengan UU No. 11/2020, Perppu 2/2022, UU No. 6/2023; Mencabut UU No. 18/1999', '{}', 'Nasional', 'Jasa Konstruksi', 'https://peraturan.bpk.go.id/Details/37637/uu-no-2-tahun-2017', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (102, 'PP', '14', 2021, 'Peraturan Pemerintah Nomor 14 Tahun 2021 tentang Perubahan atas Peraturan Pemerintah Nomor 22 Tahun 2020 tentang Peraturan Pelaksanaan Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi', 'berlaku', 'Mengubah PP No. 22/2020; Bagian dari kluster Cipta Kerja', '{}', 'Nasional', 'Jasa Konstruksi', 'https://peraturan.bpk.go.id/Details/161844/pp-no-14-tahun-2021', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (103, 'UU', '18', 2008, 'Undang-Undang Nomor 18 Tahun 2008 tentang Pengelolaan Sampah', 'berlaku', 'Berlaku penuh; belum ada perubahan formal', '{}', 'Nasional', 'Lingkungan Hidup', 'https://peraturan.bpk.go.id/Details/39067/uu-no-18-tahun-2008', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (104, 'UU', '28', 2002, 'Undang-Undang Nomor 28 Tahun 2002 tentang Bangunan Gedung', 'berlaku', 'Diubah dengan UU No. 11/2020 (Cipta Kerja) dan UU No. 6/2023; Mengatur transisi dari IMB ke PBG', '{}', 'Nasional', 'Tata Ruang', 'https://peraturan.bpk.go.id/Details/44487/uu-no-28-tahun-2002', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (105, 'PP', '16', 2021, 'Peraturan Pemerintah Nomor 16 Tahun 2021 tentang Peraturan Pelaksanaan Undang-Undang Nomor 28 Tahun 2002 tentang Bangunan Gedung', 'berlaku', 'Mencabut PP No. 36/2005; Bagian dari kluster Cipta Kerja; Mengatur transisi IMB ke PBG', '{}', 'Nasional', 'Tata Ruang', 'https://peraturan.bpk.go.id/Details/161846/pp-no-16-tahun-2021', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (106, 'PP', '10', 2021, 'Peraturan Pemerintah Nomor 10 Tahun 2021 tentang Pajak Daerah dan Retribusi Daerah dalam Rangka Mendukung Kemudahan Berusaha dan Layanan Daerah', 'berlaku', 'Bagian dari kluster Cipta Kerja; Mengatur PDRD dalam rangka kemudahan berusaha', '{}', 'Nasional', 'Keuangan Daerah', 'https://peraturan.bpk.go.id/Details/161840/pp-no-10-tahun-2021', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (107, 'PP', '35', 2021, 'Peraturan Pemerintah Nomor 35 Tahun 2021 tentang Perjanjian Kerja Waktu Tertentu, Alih Daya, Waktu Kerja dan Waktu Istirahat, dan Pemutusan Hubungan Kerja', 'berlaku', 'Bagian dari kluster Cipta Kerja; Melaksanakan UU No. 13/2003 sebagaimana diubah UU 11/2020', '{}', 'Nasional', 'Ketenagakerjaan', 'https://peraturan.bpk.go.id/Details/161904/pp-no-35-tahun-2021', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (108, 'PP', '36', 2021, 'Peraturan Pemerintah Nomor 36 Tahun 2021 tentang Pengupahan', 'berlaku', 'Bagian dari kluster Cipta Kerja; Mencabut PP No. 78/2015 tentang Pengupahan', '{}', 'Nasional', 'Ketenagakerjaan', 'https://peraturan.bpk.go.id/Details/161909/pp-no-36-tahun-2021', 'normal', '2026-09-01T11:22:04.515Z', '2026-09-01T11:22:04.515Z'),
  (109, 'Perda', '6', 2023, 'Peraturan Daerah Provinsi Kalimantan Selatan Nomor 6 Tahun 2023 tentang Rencana Tata Ruang Wilayah Provinsi Kalimantan Selatan Tahun 2023-2042', 'berlaku', 'Mencabut Perda Provinsi Kalimantan Selatan No. 9 Tahun 2015 tentang RTRWP Kalsel 2015-2035; Menyesuaikan dengan UU Cipta Kerja dan Penyangga IKN', '{}', 'Prov. Kalimantan Selatan', 'Tata Ruang', 'https://dpmptsp.kalselprov.go.id/web/download/peraturan-daerah-provinsi-kalimantan-selatan-nomor-6-tahun-2023-tentang-rencana-tata-ruang-wilayah-provinsi-kalimantan-selatan-tahun-2023-2042/', 'normal', '2026-09-01T11:35:02.538Z', '2026-09-01T11:35:02.538Z'),
  (110, 'Perda', '11', 2016, 'Peraturan Daerah Provinsi Kalimantan Selatan Nomor 11 Tahun 2016 tentang Pembentukan dan Susunan Perangkat Daerah Provinsi Kalimantan Selatan', 'berlaku', 'Melaksanakan PP No. 18/2016 tentang Perangkat Daerah; Mencabut Perda Kalsel No. 5/2008, Perda Kalsel No. 6/2008, dan Perda terkait lainnya', '{}', 'Prov. Kalimantan Selatan', 'Otonomi Daerah', 'https://peraturan.bpk.go.id/Details/39797/uu-no-40-tahun-2007', 'normal', '2026-09-01T11:35:02.556Z', '2026-09-01T11:35:02.556Z'),
  (111, 'Perda', '11', 2021, 'Peraturan Daerah Provinsi Kalimantan Selatan Nomor 11 Tahun 2021 tentang Rencana Pembangunan Jangka Menengah Daerah Provinsi Kalimantan Selatan Tahun 2021-2026', 'berlaku', 'Pedoman pembangunan daerah jangka menengah; Acuan penyusunan RKPD dan Renja SKPD Prov. Kalsel', '{}', 'Prov. Kalimantan Selatan', 'Otonomi Daerah', 'https://bappeda.kalselprov.go.id/download/rpjmd-provinsi-kalimantan-selatan-tahun-2021-2026/', 'normal', '2026-09-01T11:35:02.564Z', '2026-09-01T11:35:02.564Z');
INSERT INTO pasal (id, peraturan_id, nomor_pasal, nomor_ayat, teks_pasal) VALUES
  (228, 55, 'Pasal 18', 'Ayat (1)', 'Negara Kesatuan Republik Indonesia dibagi atas daerah-daerah provinsi dan daerah provinsi itu dibagi atas kabupaten dan kota, yang tiap-tiap provinsi, kabupaten, dan kota itu mempunyai pemerintahan daerah, yang diatur dengan undang-undang.'),
  (229, 55, 'Pasal 18', 'Ayat (6)', 'Pemerintahan daerah berhak menetapkan peraturan daerah dan peraturan-peraturan lain untuk melaksanakan otonomi dan tugas pembantuan.'),
  (230, 55, 'Pasal 18B', 'Ayat (2)', 'Negara mengakui dan menghormati kesatuan-kesatuan masyarakat hukum adat serta hak-hak tradisionalnya sepanjang masih hidup dan sesuai dengan prinsip Negara Kesatuan Republik Indonesia.'),
  (231, 55, 'Pasal 28H', 'Ayat (1)', 'Setiap orang berhak hidup sejahtera lahir dan batin, bertempat tinggal, dan mendapatkan lingkungan hidup yang baik dan sehat serta berhak memperoleh pelayanan kesehatan.'),
  (232, 55, 'Pasal 33', 'Ayat (3)', 'Bumi dan air dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besar kemakmuran rakyat.'),
  (237, 57, 'Pasal 4', 'Ayat (1)', 'Jenis Pajak yang dipungut oleh Pemerintah Provinsi terdiri atas PBBKB, PKB, BBNKB, PAP, dan Pajak Alat Berat.'),
  (238, 57, 'Pasal 94', 'Ayat (1)', 'Jenis Pajak Daerah dan Retribusi Daerah, Subjek Pajak dan Wajib Pajak, Subjek Retribusi dan Wajib Retribusi, objek Pajak dan Retribusi, dasar pengenaan Pajak, tingkat penggunaan jasa Retribusi, tarif Pajak dan Retribusi, serta tata cara penghitungan Pajak dan Retribusi ditetapkan dalam 1 (satu) Perda.'),
  (239, 58, 'Pasal 1', 'Ayat (1)', 'Menetapkan Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2022 tentang Cipta Kerja (Lembaran Negara Republik Indonesia Tahun 2022 Nomor 238, Tambahan Lembaran Negara Republik Indonesia Nomor 6841) menjadi Undang-Undang.'),
  (240, 58, 'Pasal 2', 'Ayat (1)', 'Lampiran Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2022 tentang Cipta Kerja (Lembaran Negara Republik Indonesia Tahun 2022 Nomor 238, Tambahan Lembaran Negara Republik Indonesia Nomor 6841) merupakan bagian yang tidak terpisahkan dari Undang-Undang ini.'),
  (241, 58, 'Pasal 3', 'Ayat (1)', 'Undang-Undang ini mulai berlaku pada tanggal diundangkan. Agar setiap orang mengetahuinya, memerintahkan pengundangan Undang-Undang ini dengan penempatannya dalam Lembaran Negara Republik Indonesia.'),
  (242, 58, 'Pasal 6', 'Ayat (1)', 'Peningkatan ekosistem investasi dan kegiatan berusaha meliputi penerapan perizinan berusaha berbasis risiko, penyederhanaan persyaratan dasar Perizinan Berusaha, penyederhanaan perizinan berusaha sektor, serta persyaratan investasi.'),
  (243, 58, 'Pasal 12', 'Ayat (2)', 'Pemerintah Daerah wajib menerapkan sistem Perizinan Berusaha Terintegrasi Secara Elektronik (Online Single Submission / OSS) dalam pemberian perizinan berusaha di daerah.'),
  (246, 60, 'Pasal 6', 'Ayat (2)', 'Perencanaan tata ruang dilaksanakan untuk menghasilkan Rencana Tata Ruang Wilayah (RTRW) Provinsi dan Rencana Tata Ruang Wilayah Kabupaten/Kota.'),
  (247, 60, 'Pasal 58', 'Ayat (1)', 'Kesesuaian Kegiatan Pemanfaatan Ruang (KKPR) merupakan kesesuaian antara rencana lokasi kegiatan pemanfaatan ruang dengan Rencana Tata Ruang.'),
  (248, 61, 'Pasal 3', 'Ayat (1)', 'Persetujuan Lingkungan wajib dimiliki oleh setiap Usaha dan/atau Kegiatan yang memiliki Dampak Penting atau Tidak Dampak Penting terhadap lingkungan hidup.'),
  (249, 61, 'Pasal 480', 'Ayat (2)', 'Pemerintah Daerah berwenang melakukan pengawasan terhadap penaatan pemegang Persetujuan Lingkungan di daerah.'),
  (250, 62, 'Pasal 14', 'Ayat (1)', 'Parkir insidental dapat diselenggarakan di dalam Ruang Milik Jalan, dalam hal tempat parkir di luar ruang milik jalan telah melebihi kapasitas.'),
  (251, 62, 'Pasal 14', 'Ayat (2)', 'Penyelenggaraan parkir insidental sebagaimana dimaksud pada ayat (1) dilakukan dengan pertimbangan tidak mengganggu keselamatan, ketertiban dan kelancaran lalu lintas.'),
  (252, 62, 'Pasal 14', 'Ayat (3)', 'Ruang milik jalan sebagaimana dimaksud pada ayat (1) meliputi jalan kolektor atau jalan lokal berdasarkan kawasan pengendalian parkir.'),
  (253, 62, 'Pasal 14', 'Ayat (4)', 'Penyelenggaraan parkir insidental sebagaimana dimaksud pada ayat (1) harus memperhatikan lebar jalan, volume lalu lintas, karakteristik kecepatan, dimensi kendaraan, peruntukkan lahan sekitarnya, peranan jalan bersangkutan, dan kepentingan penyandang disabilitas.'),
  (254, 62, 'Pasal 14', 'Ayat (5)', 'Fasilitas pejalan kaki dikecualikan penggunaannya sebagai fasilitas parkir dan aktivitas ekonomi.'),
  (255, 56, 'Pasal 1', 'Ayat (1)', 'Pemerintahan Daerah adalah penyelenggaraan urusan pemerintahan oleh pemerintah daerah dan dewan perwakilan rakyat daerah menurut asas otonomi dan tugas pembantuan dengan prinsip otonomi seluas-luasnya dalam sistem dan prinsip Negara Kesatuan Republik Indonesia.'),
  (256, 56, 'Pasal 2', 'Ayat (1)', 'Pemerintah Daerah Provinsi dan Kabupaten/Kota mengatur dan mengurus sendiri urusan pemerintahan menurut asas otonomi dan tugas pembantuan.'),
  (257, 56, 'Pasal 5', 'Ayat (1)', 'Urusan pemerintahan terdiri atas urusan pemerintahan absolut, urusan pemerintahan konkuren, dan urusan pemerintahan umum.'),
  (258, 56, 'Pasal 9', 'Ayat (1)', 'Urusan pemerintahan konkuren yang menjadi kewenangan Daerah terdiri atas Urusan Pemerintahan Wajib dan Urusan Pemerintahan Pilihan.'),
  (259, 56, 'Pasal 11', 'Ayat (1)', 'Urusan Pemerintahan Wajib sebagaimana dimaksud dalam Pasal 9 ayat (2) terdiri atas Urusan Pemerintahan yang berkaitan dengan Pelayanan Dasar dan Urusan Pemerintahan yang tidak berkaitan dengan Pelayanan Dasar.'),
  (260, 56, 'Pasal 12', 'Ayat (1)', 'Urusan Pemerintahan Wajib yang berkaitan dengan Pelayanan Dasar sebagaimana dimaksud dalam Pasal 11 ayat (1) meliputi pendidikan, kesehatan, pekerjaan umum dan penataan ruang, perumahan rakyat dan kawasan permukiman, ketenteraman dan ketertiban umum serta perlindungan masyarakat, dan sosial.'),
  (261, 56, 'Pasal 14', 'Ayat (1)', 'Penyelenggaraan Urusan Pemerintahan bidang kehutanan, kelautan, serta energi dan sumber daya minyak dan gas bumi dibagi antara Pemerintah Pusat dan Daerah Provinsi.'),
  (262, 56, 'Pasal 17', 'Ayat (1)', 'Daerah berhak menetapkan kebijakan Daerah untuk menyelenggarakan Urusan Pemerintahan yang menjadi kewenangan Daerah.'),
  (263, 56, 'Pasal 18', 'Ayat (1)', 'Penyelenggara Pemerintahan Daerah provinsi dan kabupaten/kota terdiri atas Kepala Daerah dan DPRD dibantu oleh Perangkat Daerah.'),
  (264, 56, 'Pasal 65', 'Ayat (1)', 'Kepala daerah mempunyai tugas memimpin pelaksanaan Urusan Pemerintahan yang menjadi kewenangan Daerah berdasarkan ketentuan peraturan perundang-undangan dan kebijakan yang ditetapkan bersama DPRD.'),
  (265, 56, 'Pasal 95', 'Ayat (1)', 'DPRD provinsi dan kabupaten/kota mempunyai fungsi pembentukan Perda, anggaran, dan pengawasan.'),
  (266, 56, 'Pasal 148', 'Ayat (1)', 'Perangkat Daerah provinsi terdiri atas sekretariat daerah, sekretariat DPRD, dinas daerah, dan badan daerah.'),
  (267, 56, 'Pasal 236', 'Ayat (1)', 'Untuk melaksanakan otonomi daerah dan tugas pembantuan, Daerah membentuk Perda.'),
  (268, 56, 'Pasal 236', 'Ayat (2)', 'Perda sebagaimana dimaksud pada ayat (1) dibentuk oleh DPRD dengan persetujuan bersama Kepala Daerah.'),
  (269, 56, 'Pasal 237', 'Ayat (1)', 'Asas pembentukan dan materi muatan Perda berpedoman pada ketentuan peraturan perundang-undangan dan asas hukum yang berkembang dalam masyarakat.'),
  (270, 56, 'Pasal 238', 'Ayat (1)', 'Perda dapat memuat ketentuan tentang pembebanan biaya paksaan penegakan hukum atau sanksi administratif.'),
  (271, 56, 'Pasal 239', 'Ayat (1)', 'Perencanaan penyusunan Perda dilakukan dalam Program Pembentukan Perda (Propemperda).'),
  (272, 56, 'Pasal 240', 'Ayat (1)', 'Rancangan Perda dapat berasal dari DPRD atau Kepala Daerah.'),
  (273, 56, 'Pasal 242', 'Ayat (1)', 'Rancangan Perda yang telah disetujui bersama oleh DPRD dan Kepala Daerah disampaikan oleh pimpinan DPRD kepada Kepala Daerah untuk ditetapkan menjadi Perda.'),
  (274, 56, 'Pasal 245', 'Ayat (1)', 'Rancangan Perda Provinsi yang mengatur tentang RTRW, pajak daerah, retribusi daerah, dan APBD wajib dievaluasi oleh Menteri sebelum ditetapkan oleh Gubernur.'),
  (275, 56, 'Pasal 246', 'Ayat (1)', 'Untuk melaksanakan Perda atau atas kuasa peraturan perundang-undangan, Kepala Daerah menetapkan Perkada.'),
  (276, 59, 'Pasal 1', 'Ayat (1)', 'Keuangan Daerah adalah semua hak dan kewajiban Daerah dalam rangka penyelenggaraan Pemerintahan Daerah yang dapat dinilai dengan uang serta segala bentuk kekayaan yang dapat dijadikan milik Daerah berhubung dengan hak dan kewajiban Daerah tersebut.'),
  (277, 59, 'Pasal 2', 'Ayat (1)', 'Pengelolaan Keuangan Daerah mencakup keseluruhan kegiatan yang meliputi perencanaan, penganggaran, pelaksanaan, penatausahaan, pelaporan, pertanggungjawaban, dan pengawasan keuangan daerah.'),
  (278, 59, 'Pasal 3', 'Ayat (1)', 'Pengelolaan Keuangan Daerah dilakukan secara tertib, taat pada ketentuan peraturan perundang-undangan, efisien, ekonomis, efektif, transparan, dan bertanggung jawab dengan memperhatikan rasa keadilan, kepatutan, dan manfaat untuk masyarakat.'),
  (279, 59, 'Pasal 4', 'Ayat (1)', 'Kepala Daerah selaku pemegang kekuasaan pengelolaan keuangan daerah mewakili pemerintah daerah dalam kepemilikan kekayaan daerah yang dipisahkan.'),
  (280, 59, 'Pasal 10', 'Ayat (1)', 'Pejabat Pengelola Keuangan Daerah (PPKD) mempunyai tugas menyusun dan melaksanakan kebijakan pengelolaan APBD.'),
  (281, 59, 'Pasal 24', 'Ayat (1)', 'Penganggaran penerimaan dan pengeluaran APBD harus didasarkan pada Kepastian Hukum dan Asas Umum Pengelolaan Keuangan Daerah.'),
  (282, 59, 'Pasal 27', 'Ayat (1)', 'Pendapatan Daerah terdiri atas Pendapatan Asli Daerah (PAD), Pendapatan Transfer, dan Lain-lain Pendapatan Daerah yang sah.'),
  (283, 59, 'Pasal 50', 'Ayat (1)', 'Belanja Daerah disusun berdasarkan pendekatan prestasi kerja yang berorientasi pada pencapaian hasil dari input yang direncanakan.'),
  (284, 63, 'Pasal 1', 'Ayat (1)', 'Keuangan Negara adalah semua hak dan kewajiban negara yang dapat dinilai dengan uang, serta segala sesuatu baik berupa uang maupun berupa barang yang dapat dijadikan milik negara berhubung dengan pelaksanaan hak dan kewajiban tersebut.'),
  (285, 63, 'Pasal 3', 'Ayat (1)', 'Keuangan Negara dikelola secara tertib, taat pada peraturan perundang-undangan, efisien, ekonomis, efektif, transparan, dan bertanggung jawab dengan memperhatikan rasa keadilan dan kepatutan.'),
  (286, 63, 'Pasal 6', 'Ayat (1)', 'Presiden selaku Kepala Pemerintahan memegang kekuasaan pengelolaan keuangan negara sebagai bagian dari kekuasaan pemerintahan.'),
  (287, 64, 'Pasal 1', 'Ayat (1)', 'Perbendaharaan Negara adalah pengelolaan dan pertanggungjawaban keuangan negara, termasuk investasi dan kekayaan yang dipisahkan, yang ditetapkan dalam APBN dan APBD.'),
  (288, 64, 'Pasal 12', 'Ayat (1)', 'Semua penerimaan dan pengeluaran negara/daerah dilakukan melalui Rekening Kas Umum Negara/Daerah.'),
  (289, 65, 'Pasal 2', 'Ayat (1)', 'Pembangunan Nasional diselenggarakan berdasarkan demokrasi dengan prinsip-prinsip kebersamaan, berkeadilan, berkelanjutan, berwawasan lingkungan, serta kemandirian dengan menjaga keseimbangan kemajuan dan kesatuan nasional.'),
  (290, 65, 'Pasal 5', 'Ayat (2)', 'RPJMD memuat arah kebijakan keuangan Daerah, strategi pembangunan Daerah, kebijakan umum, dan program Satuan Kerja Perangkat Daerah.'),
  (291, 66, 'Pasal 3', 'Ayat (1)', 'Penyelenggaraan penataan ruang bertujuan untuk mewujudkan ruang wilayah nasional yang aman, nyaman, produktif, dan berkelanjutan berlandaskan Wawasan Nusantara dan Ketahanan Nasional.'),
  (292, 66, 'Pasal 26', 'Ayat (1)', 'Rencana Tata Ruang Wilayah (RTRW) Kabupaten memuat tujuan, kebijakan, dan strategi penataan ruang wilayah kabupaten.'),
  (293, 67, 'Pasal 1', 'Ayat (1)', 'Lingkungan hidup adalah kesatuan ruang dengan semua benda, daya, keadaan, dan makhluk hidup, termasuk manusia dan perilakunya, yang mempengaruhi alam itu sendiri, kelangsungan perkehidupan, dan kesejahteraan manusia serta makhluk hidup lain.'),
  (294, 67, 'Pasal 65', 'Ayat (1)', 'Setiap orang berhak atas lingkungan hidup yang baik dan sehat sebagai bagian dari hak asasi manusia.'),
  (295, 68, 'Pasal 4', 'Ayat (1)', 'Setiap orang berhak atas kesehatan.'),
  (296, 68, 'Pasal 171', 'Ayat (1)', 'Besar anggaran kesehatan Pemerintah Daerah Provinsi, Kabupaten/Kota dialokasikan minimal 10% dari APBD di luar gaji.'),
  (297, 69, 'Pasal 5', 'Ayat (1)', 'Setiap warga negara mempunyai hak yang sama untuk memperoleh pendidikan yang bermutu.'),
  (298, 69, 'Pasal 49', 'Ayat (1)', 'Dana pendidikan selain gaji pendidik dan biaya pendidikan kedinasan dialokasikan minimal 20% dari Anggaran Pendapatan dan Belanja Negara (APBN) pada sektor pendidikan dan minimal 20% dari Anggaran Pendapatan dan Belanja Daerah (APBD).'),
  (299, 70, 'Pasal 5', 'Ayat (1)', 'Setiap tenaga kerja memiliki kesempatan yang sama tanpa diskriminasi untuk memperoleh pekerjaan.'),
  (300, 70, 'Pasal 88', 'Ayat (1)', 'Setiap pekerja/buruh berhak memperoleh penghasilan yang memenuhi penghidupan yang layak bagi kemanusiaan.'),
  (301, 71, 'Pasal 3', 'Ayat (1)', 'Penanaman modal diselenggarakan berdasarkan asas kepastian hukum, keterbukaan, akuntabilitas, perlakuan yang sama dan tidak membedakan asal negara, kebersamaan, efisiensi berkeadilan, berkelanjutan, berwawasan lingkungan, kemandirian, dan keseimbangan kemajuan dan kesatuan ekonomi nasional.'),
  (302, 72, 'Pasal 2', 'Ayat (1)', 'Jenis Pajak provinsi terdiri atas Pajak Kendaraan Bermotor, Bea Balik Nama Kendaraan Bermotor, Pajak Bahan Bakar Kendaraan Bermotor, Pajak Air Permukaan, dan Pajak Rokok.'),
  (303, 73, 'Pasal 1', 'Angka 1', 'Pembentukan Peraturan Perundang-undangan adalah pembuatan Peraturan Perundang-undangan yang mencakup tahapan perencanaan, penyusunan, pembahasan, pengesahan atau penetapan, dan pengundangan.'),
  (304, 73, 'Pasal 5', 'Huruf a', 'Dalam membentuk Peraturan Perundang-undangan harus dilakukan berdasarkan pada asas pembentukan Peraturan Perundang-undangan yang baik, yang meliputi: a. kejelasan tujuan.'),
  (305, 73, 'Pasal 7', 'Ayat (1)', 'Jenis dan hierarki Peraturan Perundang-undangan terdiri atas: a. Undang-Undang Dasar Negara Republik Indonesia Tahun 1945; b. Ketetapan Majelis Permusyawaratan Rakyat; c. Undang-Undang/Peraturan Pemerintah Pengganti Undang-Undang; d. Peraturan Pemerintah; e. Peraturan Presiden; f. Peraturan Daerah Provinsi; dan g. Peraturan Daerah Kabupaten/Kota.'),
  (306, 73, 'Pasal 14', '', 'Materi muatan Peraturan Daerah Provinsi dan Peraturan Daerah Kabupaten/Kota berisi materi muatan dalam rangka penyelenggaraan otonomi daerah dan tugas pembantuan serta menampung kondisi khusus daerah dan/atau penjabaran lebih lanjut Peraturan Perundang-undangan yang lebih tinggi.'),
  (307, 73, 'Pasal 58', 'Ayat (1)', 'Masyarakat berhak memberikan masukan secara lisan dan/atau tertulis dalam Pembentukan Peraturan Perundang-undangan.'),
  (308, 73, 'Pasal 96', 'Ayat (1)', 'Masyarakat berhak memberikan masukan secara lisan dan/atau tertulis dalam Pembentukan Peraturan Perundang-undangan.'),
  (309, 74, 'Pasal I', '', 'Beberapa ketentuan dalam Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah diubah sebagai berikut...'),
  (310, 74, 'Pasal 101', 'Ayat (1)', 'DPRD provinsi mempunyai tugas dan wewenang: membentuk Perda Provinsi bersama Gubernur.'),
  (311, 75, 'Pasal 5', 'Ayat (1)', 'Satpol PP mempunyai tugas menegakkan Peraturan Daerah dan Peraturan Kepala Daerah, menyelenggarakan ketertiban umum dan ketenteraman, serta menyelenggarakan pelindungan masyarakat.'),
  (312, 75, 'Pasal 6', 'Huruf a', 'Dalam melaksanakan tugas sebagaimana dimaksud dalam Pasal 5, Satpol PP mempunyai fungsi: a. penyusunan program penegakan Perda dan Peraturan Kepala Daerah, penyelenggaraan ketertiban umum dan ketenteraman serta pelindungan masyarakat.'),
  (313, 76, 'Pasal 2', 'Ayat (1)', 'Pembinaan penyelenggaraan Pemerintahan Daerah dilakukan oleh Pemerintah Pusat.'),
  (314, 76, 'Pasal 9', 'Ayat (1)', 'Pengawasan penyelenggaraan Pemerintahan Daerah dilaksanakan oleh Aparat Pengawas Internal Pemerintah.'),
  (315, 77, 'Pasal 1', 'Angka 1', 'Kesehatan adalah keadaan sehat seseorang, baik secara fisik, jiwa, maupun sosial dan bukan sekadar bebas dari penyakit, yang memungkinkan setiap orang untuk hidup produktif.'),
  (316, 77, 'Pasal 4', 'Ayat (1)', 'Setiap orang mempunyai hak yang sama dalam memperoleh akses atas sumber daya di bidang kesehatan.'),
  (317, 77, 'Pasal 7', '', 'Pemerintah Pusat dan Pemerintah Daerah bertanggung jawab atas penyelenggaraan kesehatan.'),
  (318, 78, 'Pasal 1', 'Angka 1', 'Perizinan Berusaha Berbasis Risiko adalah Perizinan Berusaha berdasarkan tingkat risiko kegiatan usaha.'),
  (319, 78, 'Pasal 4', 'Ayat (1)', 'Perizinan Berusaha terdiri atas: a. Nomor Induk Berusaha (NIB); b. Sertifikat Standar; dan c. Izin.'),
  (320, 78, 'Pasal 9', 'Ayat (1)', 'Penerbitan NIB dilakukan melalui sistem OSS setelah Pelaku Usaha mengisi data secara benar, lengkap, dan akurat.'),
  (322, 80, 'Pasal 3', 'Ayat (1)', 'Setiap orang yang akan mendirikan bangunan gedung wajib memiliki Izin Mendirikan Bangunan (IMB).'),
  (323, 80, 'Pasal 8', 'Ayat (1)', 'Permohonan IMB diajukan secara tertulis kepada Walikota atau pejabat yang ditunjuk.'),
  (324, 81, 'Pasal 4', 'Huruf a', 'Pengelolaan sampah diselenggarakan berdasarkan asas tanggung jawab.'),
  (325, 81, 'Pasal 10', 'Ayat (1)', 'Setiap orang wajib mengurangi dan menangani sampah dengan cara yang berwawasan lingkungan.'),
  (326, 82, 'Pasal 3', 'Ayat (1)', 'Jenis pajak yang dipungut oleh Kota Banjarbaru antara lain Pajak Hotel, Pajak Restoran, Pajak Hiburan, Pajak Reklame, Pajak Penerangan Jalan, dan Pajak Bumi dan Bangunan Perdesaan dan Perkotaan.'),
  (327, 83, 'Pasal 7', 'Ayat (1)', 'Setiap pengusaha wajib melaksanakan ketentuan waktu kerja sesuai dengan peraturan perundang-undangan yang berlaku.'),
  (328, 83, 'Pasal 12', 'Ayat (1)', 'Setiap pengusaha wajib memberikan upah kepada pekerja/buruh sesuai dengan ketentuan upah minimum yang ditetapkan.'),
  (329, 84, 'Pasal 1', 'Angka 1', 'Ruang wilayah Kabupaten Tanah Laut adalah ruang yang merupakan kesatuan geografis beserta segenap unsur terkait yang batas dan sistemnya ditentukan berdasarkan aspek administratif dan/atau aspek fungsional.'),
  (330, 84, 'Pasal 5', 'Ayat (1)', 'Rencana struktur ruang wilayah Kabupaten Tanah Laut meliputi: a. rencana pengembangan sistem perkotaan; dan b. rencana pengembangan sistem jaringan prasarana.'),
  (331, 85, 'Pasal 1', 'Angka 1', 'Perangkat Daerah adalah unsur pembantu kepala Daerah dan Dewan Perwakilan Rakyat Daerah dalam penyelenggaraan Urusan Pemerintahan yang menjadi kewenangan Daerah.'),
  (332, 85, 'Pasal 5', 'Ayat (1)', 'Pembentukan dan susunan Perangkat Daerah ditetapkan dengan Peraturan Daerah.'),
  (333, 85, 'Pasal 6', 'Ayat (1)', 'Perangkat Daerah Provinsi terdiri atas: a. sekretariat daerah; b. sekretariat DPRD; c. inspektorat daerah; d. dinas; dan e. badan.'),
  (334, 86, 'Pasal 1', 'Angka 1', 'Kecamatan atau yang disebut dengan nama lain adalah bagian wilayah dari Daerah kabupaten/kota yang dipimpin oleh camat.'),
  (335, 86, 'Pasal 10', 'Ayat (1)', 'Camat mempunyai tugas menyelenggarakan urusan pemerintahan umum, sebagaimana dimaksud dalam Pasal 25 ayat (6) Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.'),
  (336, 87, 'Pasal 1', 'Angka 1', 'Desa adalah desa dan desa adat atau yang disebut dengan nama lain, selanjutnya disebut Desa, adalah kesatuan masyarakat hukum yang memiliki batas wilayah yang berwenang untuk mengatur dan mengurus urusan pemerintahan, kepentingan masyarakat setempat berdasarkan prakarsa masyarakat, hak asal usul, dan/atau hak tradisional yang diakui dan dihormati dalam sistem pemerintahan Negara Kesatuan Republik Indonesia.'),
  (337, 87, 'Pasal 93', 'Ayat (1)', 'Pengelolaan keuangan Desa meliputi: a. perencanaan; b. pelaksanaan; c. penatausahaan; d. pelaporan; dan e. pertanggungjawaban.'),
  (338, 88, 'Pasal 1', 'Angka 1', 'Jasa Konstruksi adalah layanan jasa konsultansi konstruksi dan/atau pekerjaan konstruksi.'),
  (339, 88, 'Pasal 3', 'Ayat (1)', 'Pemerintah Daerah Provinsi berwenang melakukan penyelenggaraan jasa konstruksi di wilayah Provinsi Kalimantan Selatan.'),
  (340, 89, 'Pasal 1', 'Angka 1', 'Cipta Kerja adalah upaya penciptaan kerja melalui usaha kemudahan, perlindungan, dan pemberdayaan koperasi dan usaha mikro, kecil, dan menengah, peningkatan ekosistem investasi dan kemudahan berusaha, dan investasi Pemerintah Pusat dan percepatan proyek strategis nasional.'),
  (341, 89, 'Pasal 4', 'Ayat (1)', 'Penyederhanaan persyaratan dasar Perizinan Berusaha meliputi: a. kesesuaian kegiatan pemanfaatan ruang; b. Persetujuan Bangunan Gedung dan Sertifikat Laik Fungsi; c. persetujuan lingkungan.'),
  (342, 89, 'Pasal 6', '', 'Peningkatan ekosistem investasi dan kegiatan berusaha sebagaimana dimaksud dalam Pasal 5 huruf a meliputi: a. penerapan Perizinan Berusaha berbasis risiko; b. penyederhanaan persyaratan investasi; c. penyederhanaan persyaratan Perizinan Berusaha.'),
  (343, 89, 'Pasal 185', 'Huruf b', 'Pemerintah Daerah wajib menyesuaikan Peraturan Daerah yang berkaitan dengan kemudahan berusaha dan investasi paling lambat 3 (tiga) bulan sejak Undang-Undang ini berlaku.'),
  (344, 90, 'Pasal 1', 'Ayat (1)', 'Tidak ada seorang pun yang dapat dipidana atau dikenai tindakan, kecuali perbuatan yang dilakukan patut dipersalahkan sesuai dengan ketentuan undang-undang yang berlaku pada saat perbuatan itu dilakukan.'),
  (345, 90, 'Pasal 2', 'Ayat (1)', 'Ketentuan dalam Buku Kesatu berlaku bagi perbuatan yang dapat dipidana berdasarkan ketentuan peraturan perundang-undangan lain, termasuk Peraturan Daerah Provinsi dan Peraturan Daerah Kabupaten/Kota, kecuali ditentukan lain menurut undang-undang.'),
  (346, 90, 'Pasal 599', 'Ayat (1)', 'Dipidana dengan pidana denda paling banyak kategori II, setiap orang yang melanggar Peraturan Daerah Provinsi atau Peraturan Daerah Kabupaten/Kota.'),
  (347, 90, 'Pasal 622', 'Ayat (1)', 'Pada saat Undang-Undang ini mulai berlaku, beberapa undang-undang yang mengatur ketentuan pidana dinyatakan masih tetap berlaku sepanjang tidak bertentangan dengan Undang-Undang ini.'),
  (348, 91, 'Pasal 1', '', 'Undang-Undang ini mengatur mengenai penyesuaian terhadap ketentuan pidana dalam setiap Undang-Undang di luar Undang-Undang Nomor 1 Tahun 2023 tentang Kitab Undang-Undang Hukum Pidana dan Peraturan Daerah dengan Buku Kesatu Undang-Undang Nomor 1 Tahun 2023.'),
  (349, 91, 'Pasal 238', '', 'Ketentuan Pasal 238 Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah diubah sehingga berbunyi: sanksi administratif yang dikenakan kepada Kepala Daerah dan DPRD disesuaikan dengan ketentuan dalam Undang-Undang Nomor 1 Tahun 2023.'),
  (350, 92, 'Pasal I', '', 'Beberapa ketentuan dalam Undang-Undang Nomor 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-undangan diubah, termasuk penambahan mekanisme pembahasan RUU yang sudah dibahas pada periode sebelumnya dan pengaturan mengenai Pemantauan dan Peninjauan Peraturan Perundang-undangan.'),
  (351, 92, 'Pasal 95A', 'Ayat (1)', 'DPR, DPD, dan Presiden melakukan Pemantauan dan Peninjauan terhadap Undang-Undang.'),
  (352, 92, 'Pasal 95B', 'Ayat (1)', 'Menteri, kepala lembaga, atau kepala daerah melakukan pemantauan dan peninjauan terhadap Peraturan Perundang-undangan di bawah Undang-Undang.'),
  (353, 93, 'Pasal I', '', 'Beberapa ketentuan dalam Undang-Undang Nomor 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-undangan diubah, termasuk penambahan metode omnibus, penguatan meaningful participation, dan pembentukan peraturan perundang-undangan secara elektronik.'),
  (354, 93, 'Pasal 9A', 'Ayat (1)', 'Pembentukan Peraturan Perundang-undangan dapat menggunakan metode omnibus.'),
  (355, 93, 'Pasal 96', 'Ayat (1)', 'Masyarakat berhak memberikan masukan secara lisan dan/atau tertulis dalam setiap tahapan Pembentukan Peraturan Perundang-undangan.'),
  (356, 93, 'Pasal 96', 'Ayat (4)', 'Masyarakat yang terdampak langsung atau memiliki kepentingan atas materi muatan Rancangan Peraturan Perundang-undangan berhak: a. memberikan masukan secara lisan dan/atau tertulis; b. mendapatkan penjelasan; dan c. mendapatkan laporan atas masukannya.'),
  (357, 94, 'Pasal 1', 'Angka 1', 'Administrasi Pemerintahan adalah tata laksana dalam pengambilan keputusan dan/atau tindakan oleh badan dan/atau pejabat pemerintahan.'),
  (358, 94, 'Pasal 5', '', 'Penyelenggaraan Administrasi Pemerintahan berdasarkan pada asas: a. legalitas; b. perlindungan hukum; c. kepastian hukum; d. ketidakberpihakan; e. kecermatan; f. tidak menyalahgunakan kewenangan; g. keterbukaan; h. kepentingan umum; dan i. pelayanan yang baik.'),
  (359, 94, 'Pasal 9', 'Ayat (1)', 'Setiap Keputusan dan/atau Tindakan wajib berdasarkan ketentuan peraturan perundang-undangan dan AUPB.'),
  (360, 94, 'Pasal 14', 'Ayat (1)', 'Badan dan/atau Pejabat Pemerintahan yang menggunakan Diskresi harus memenuhi syarat: a. sesuai dengan tujuan Diskresi; b. tidak bertentangan dengan ketentuan peraturan perundang-undangan; c. sesuai dengan AUPB; d. berdasarkan alasan-alasan yang objektif; e. tidak menimbulkan konflik kepentingan; dan f. dilakukan dengan iktikad baik.'),
  (361, 95, 'Pasal 1', 'Angka 1', 'Pelayanan publik adalah kegiatan atau rangkaian kegiatan dalam rangka pemenuhan kebutuhan pelayanan sesuai dengan peraturan perundang-undangan bagi setiap warga negara dan penduduk atas barang, jasa, dan/atau pelayanan administratif yang disediakan oleh penyelenggara pelayanan publik.'),
  (362, 95, 'Pasal 4', '', 'Penyelenggaraan pelayanan publik berasaskan: a. kepentingan umum; b. kepastian hukum; c. kesamaan hak; d. keseimbangan hak dan kewajiban; e. keprofesionalan; f. partisipatif; g. persamaan perlakuan/tidak diskriminatif; h. keterbukaan; i. akuntabilitas; j. fasilitas dan perlakuan khusus bagi kelompok rentan; k. ketepatan waktu; dan l. kecepatan, kemudahan, dan keterjangkauan.'),
  (363, 95, 'Pasal 20', 'Ayat (1)', 'Penyelenggara berkewajiban menyusun dan menetapkan standar pelayanan dengan memperhatikan kemampuan penyelenggara, kebutuhan masyarakat, dan kondisi lingkungan.'),
  (364, 96, 'Pasal 2', 'Ayat (1)', 'Setiap Informasi Publik bersifat terbuka dan dapat diakses oleh setiap Pengguna Informasi Publik.'),
  (365, 96, 'Pasal 7', 'Ayat (1)', 'Badan Publik wajib menyediakan, memberikan dan/atau menerbitkan Informasi Publik yang berada di bawah kewenangannya kepada Pemohon Informasi Publik, selain informasi yang dikecualikan sesuai dengan ketentuan.'),
  (366, 96, 'Pasal 9', 'Ayat (1)', 'Setiap Badan Publik wajib mengumumkan Informasi Publik secara berkala.'),
  (367, 97, 'Pasal 1', 'Angka 1', 'Desa adalah desa dan desa adat atau yang disebut dengan nama lain, selanjutnya disebut Desa, adalah kesatuan masyarakat hukum yang memiliki batas wilayah yang berwenang untuk mengatur dan mengurus urusan pemerintahan, kepentingan masyarakat setempat berdasarkan prakarsa masyarakat, hak asal usul, dan/atau hak tradisional yang diakui dan dihormati dalam sistem pemerintahan Negara Kesatuan Republik Indonesia.'),
  (368, 97, 'Pasal 26', 'Ayat (1)', 'Kepala Desa bertugas menyelenggarakan Pemerintahan Desa, melaksanakan Pembangunan Desa, pembinaan kemasyarakatan Desa, dan pemberdayaan masyarakat Desa.'),
  (369, 97, 'Pasal 69', 'Ayat (1)', 'Jenis peraturan di Desa terdiri atas Peraturan Desa, peraturan bersama Kepala Desa, dan peraturan Kepala Desa.'),
  (370, 97, 'Pasal 72', 'Ayat (1)', 'Pendapatan Desa bersumber dari: a. pendapatan asli Desa; b. alokasi Anggaran Pendapatan dan Belanja Negara; c. bagian dari hasil pajak daerah dan retribusi daerah; d. alokasi dana desa; e. bantuan keuangan dari APBD Provinsi dan APBD Kabupaten/Kota; f. hibah dan sumbangan yang tidak mengikat dari pihak ketiga; g. lain-lain pendapatan Desa yang sah.'),
  (371, 98, 'Pasal I', '', 'Beberapa ketentuan dalam Undang-Undang Nomor 6 Tahun 2014 tentang Desa sebagaimana telah diubah dengan Undang-Undang Nomor 6 Tahun 2023 diubah, termasuk ketentuan mengenai masa jabatan Kepala Desa.'),
  (372, 98, 'Pasal 39', 'Ayat (1)', 'Kepala Desa memegang jabatan selama 8 (delapan) tahun terhitung sejak tanggal pelantikan.'),
  (373, 98, 'Pasal 39', 'Ayat (2)', 'Kepala Desa sebagaimana dimaksud pada ayat (1) dapat menjabat paling banyak 2 (dua) kali masa jabatan secara berturut-turut atau tidak secara berturut-turut.'),
  (374, 99, 'Pasal 81', 'Ayat (1)', 'Penghasilan tetap diberikan kepada kepala desa, sekretaris desa, dan perangkat desa lainnya dianggarkan dalam APBDesa yang bersumber dari ADD atau sumber lain dalam APBDesa selain dana desa.'),
  (375, 99, 'Pasal 81A', 'Ayat (1)', 'Besaran penghasilan tetap kepala desa paling sedikit Rp2.426.640 (dua juta empat ratus dua puluh enam ribu enam ratus empat puluh rupiah) setara 120% gaji pokok PNS golongan ruang II/a.'),
  (376, 100, 'Pasal I', '', 'Beberapa ketentuan dalam Peraturan Pemerintah Nomor 18 Tahun 2016 tentang Perangkat Daerah diubah untuk memperkuat peran dan independensi Inspektorat Daerah serta mengatur tata kelola Rumah Sakit Daerah.'),
  (377, 100, 'Pasal 11A', 'Ayat (1)', 'Inspektur Daerah provinsi diangkat dan diberhentikan oleh gubernur setelah berkonsultasi dengan Menteri Dalam Negeri.'),
  (378, 100, 'Pasal 11B', 'Ayat (1)', 'Untuk mendukung pelaksanaan tugas Inspektorat Daerah, dapat dibentuk Unit Pelaksana Teknis Daerah pada Inspektorat Daerah.'),
  (379, 101, 'Pasal 1', 'Angka 1', 'Jasa Konstruksi adalah layanan jasa konsultansi konstruksi dan/atau pekerjaan konstruksi.'),
  (380, 101, 'Pasal 7', 'Ayat (1)', 'Kewenangan Pemerintah Pusat meliputi: a. penetapan kebijakan pengembangan Jasa Konstruksi nasional; b. penyelenggaraan registrasi badan usaha Jasa Konstruksi; c. penyelenggaraan registrasi pengalaman badan usaha Jasa Konstruksi; d. penyelenggaraan akreditasi asosiasi badan usaha Jasa Konstruksi; e. pembentukan lembaga.'),
  (381, 101, 'Pasal 8', 'Ayat (1)', 'Kewenangan Pemerintah Daerah Provinsi dalam penyelenggaraan Jasa Konstruksi meliputi: a. penyelenggaraan pelatihan tenaga ahli konstruksi; b. penyelenggaraan sistem informasi Jasa Konstruksi.'),
  (382, 101, 'Pasal 14', 'Ayat (1)', 'Usaha Jasa Konstruksi mencakup jenis usaha, sifat usaha, dan klasifikasi usaha Jasa Konstruksi.'),
  (383, 102, 'Pasal I', '', 'Beberapa ketentuan dalam Peraturan Pemerintah Nomor 22 Tahun 2020 tentang Peraturan Pelaksanaan Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi diubah dalam rangka pelaksanaan Undang-Undang Nomor 11 Tahun 2020 tentang Cipta Kerja.'),
  (384, 102, 'Pasal 1', 'Angka 10', 'Perizinan Berusaha adalah legalitas yang diberikan kepada Pelaku Usaha untuk memulai dan menjalankan usaha dan/atau kegiatan Jasa Konstruksi.'),
  (385, 103, 'Pasal 1', 'Angka 1', 'Sampah adalah sisa kegiatan sehari-hari manusia dan/atau proses alam yang berbentuk padat.'),
  (386, 103, 'Pasal 5', '', 'Pemerintah dan pemerintahan daerah bertugas menjamin terselenggaranya pengelolaan sampah yang baik dan berwawasan lingkungan sesuai dengan tujuan Undang-Undang ini.'),
  (387, 103, 'Pasal 9', 'Ayat (1)', 'Pemerintahan kabupaten/kota mempunyai kewenangan: a. menetapkan kebijakan dan strategi pengelolaan sampah berdasarkan kebijakan nasional dan provinsi; b. menyelenggarakan pengelolaan sampah skala kabupaten/kota sesuai dengan norma, standar, prosedur, dan kriteria yang ditetapkan oleh Pemerintah; c. melakukan pembinaan dan pengawasan kinerja pengelolaan sampah yang dilaksanakan oleh pihak lain.'),
  (388, 103, 'Pasal 29', 'Ayat (1)', 'Setiap orang dilarang: a. membuang sampah tidak pada tempat yang telah ditentukan dan disediakan; b. melakukan penanganan sampah dengan pembuangan terbuka di lahan terbuka; c. membakar sampah yang tidak sesuai dengan persyaratan teknis pengelolaan sampah.'),
  (389, 104, 'Pasal 1', 'Angka 1', 'Bangunan gedung adalah wujud fisik hasil pekerjaan konstruksi yang menyatu dengan tempat kedudukannya, sebagian atau seluruhnya berada di atas dan/atau di dalam tanah dan/atau air, yang berfungsi sebagai tempat manusia melakukan kegiatannya, baik untuk hunian atau tempat tinggal, kegiatan keagamaan, kegiatan usaha, kegiatan sosial, budaya, maupun kegiatan khusus.'),
  (390, 104, 'Pasal 7', 'Ayat (1)', 'Setiap bangunan gedung harus memenuhi persyaratan administratif dan persyaratan teknis sesuai dengan fungsi bangunan gedung.'),
  (391, 104, 'Pasal 35', 'Ayat (1)', 'Pemerintah daerah wajib menerbitkan Persetujuan Bangunan Gedung sesuai dengan ketentuan peraturan perundang-undangan.'),
  (392, 105, 'Pasal 1', 'Angka 6', 'Persetujuan Bangunan Gedung yang selanjutnya disingkat PBG adalah perizinan yang diberikan kepada pemilik Bangunan Gedung untuk membangun baru, mengubah, memperluas, mengurangi, dan/atau merawat Bangunan Gedung sesuai dengan standar teknis Bangunan Gedung.'),
  (393, 105, 'Pasal 347', 'Ayat (1)', 'Izin Mendirikan Bangunan yang telah diterbitkan sebelum berlakunya Peraturan Pemerintah ini dinyatakan tetap berlaku.'),
  (394, 105, 'Pasal 350', '', 'Pemerintah Daerah wajib melakukan penyesuaian Peraturan Daerah tentang bangunan gedung dengan ketentuan Peraturan Pemerintah ini paling lambat 1 (satu) tahun sejak berlakunya Peraturan Pemerintah ini.'),
  (395, 106, 'Pasal 1', 'Angka 1', 'Pajak Daerah, yang selanjutnya disebut Pajak, adalah kontribusi wajib kepada Daerah yang terutang oleh orang pribadi atau badan yang bersifat memaksa berdasarkan Undang-Undang, dengan tidak mendapatkan imbalan secara langsung dan digunakan untuk keperluan Daerah bagi sebesar-besarnya kemakmuran rakyat.'),
  (396, 106, 'Pasal 4', 'Ayat (1)', 'Peraturan Daerah tentang PDRD yang tidak sesuai dengan ketentuan peraturan perundang-undangan yang lebih tinggi dinyatakan tidak berlaku dan harus disesuaikan.'),
  (397, 106, 'Pasal 8', 'Ayat (1)', 'Kepala Daerah melalui Menteri melaporkan Peraturan Daerah yang mengatur PDRD kepada Pemerintah Pusat.'),
  (398, 107, 'Pasal 1', 'Angka 1', 'Perjanjian Kerja Waktu Tertentu yang selanjutnya disingkat PKWT adalah perjanjian kerja antara pekerja/buruh dengan pengusaha untuk mengadakan hubungan kerja dalam waktu tertentu atau untuk pekerjaan tertentu.'),
  (399, 107, 'Pasal 5', 'Ayat (1)', 'PKWT berdasarkan jangka waktu dibuat untuk paling lama 5 (lima) tahun.'),
  (400, 107, 'Pasal 37', 'Ayat (1)', 'Waktu kerja paling lama 8 (delapan) jam 1 (satu) hari dan 40 (empat puluh) jam 1 (satu) minggu, untuk 5 (lima) hari kerja dalam 1 (satu) minggu.'),
  (401, 107, 'Pasal 40', 'Ayat (1)', 'Pemutusan Hubungan Kerja mengakibatkan pengusaha wajib membayar uang pesangon, uang penghargaan masa kerja, dan/atau uang penggantian hak sesuai ketentuan.'),
  (402, 108, 'Pasal 1', 'Angka 1', 'Upah adalah hak pekerja/buruh yang diterima dan dinyatakan dalam bentuk uang sebagai imbalan dari pengusaha atau pemberi kerja kepada pekerja/buruh yang ditetapkan dan dibayarkan menurut suatu perjanjian kerja, kesepakatan, atau peraturan perundang-undangan.'),
  (403, 108, 'Pasal 26', 'Ayat (1)', 'Gubernur menetapkan Upah Minimum Provinsi setiap tahun berdasarkan kondisi ekonomi dan ketenagakerjaan.'),
  (404, 108, 'Pasal 33', 'Ayat (1)', 'Bupati/Wali Kota dapat menetapkan UMK dengan syarat lebih besar dari UMP.'),
  (405, 109, 'Pasal 1', 'Angka 1', 'Rencana Tata Ruang Wilayah Provinsi Kalimantan Selatan yang selanjutnya disingkat RTRW Provinsi adalah rencana tata ruang yang mengatur struktur ruang dan pola ruang wilayah Provinsi Kalimantan Selatan.'),
  (406, 109, 'Pasal 3', '', 'Penataan ruang wilayah Provinsi bertujuan untuk mewujudkan Kalimantan Selatan sebagai Gerbang Logistik Kalimantan dan Pintu Gerbang Ibu Kota Nusantara yang mandiri, berdaya saing, berkelanjutan, dan berbasis agribisnis serta industri kelautan.'),
  (407, 109, 'Pasal 47', 'Ayat (1)', 'Kesesuaian Kegiatan Pemanfaatan Ruang (KKPR) menjadi acuan utama dalam penerbitan perizinan berusaha dan perizinan nonberusaha di daerah.'),
  (408, 109, 'Pasal 98', 'Ayat (1)', 'Pemerintah Kabupaten/Kota di wilayah Kalimantan Selatan wajib menyesuaikan RTRW Kabupaten/Kota dengan RTRW Provinsi paling lambat 2 (dua) tahun sejak Peraturan Daerah ini diundangkan.'),
  (409, 110, 'Pasal 1', 'Angka 1', 'Perangkat Daerah Provinsi adalah unsur pembantu Gubernur dan Dewan Perwakilan Rakyat Daerah Provinsi dalam penyelenggaraan Urusan Pemerintahan yang menjadi kewenangan Daerah Provinsi.'),
  (410, 110, 'Pasal 2', '', 'Dengan Peraturan Daerah ini dibentuk Perangkat Daerah dengan susunan: Sekretariat Daerah, Sekretariat DPRD, Inspektorat Daerah, Dinas Daerah, dan Badan Daerah.'),
  (411, 110, 'Pasal 4', 'Ayat (1)', 'Dinas Daerah Provinsi merupakan unsur pelaksana Urusan Pemerintahan yang menjadi kewenangan Daerah Provinsi yang dipimpin oleh Kepala Dinas.'),
  (412, 110, 'Pasal 12', '', 'Ketentuan lebih lanjut mengenai kedudukan, susunan organisasi, tugas, fungsi, dan tata kerja Perangkat Daerah diatur dengan Peraturan Gubernur.'),
  (413, 111, 'Pasal 1', 'Angka 1', 'Rencana Pembangunan Jangka Menengah Daerah Provinsi Kalimantan Selatan Tahun 2021-2026 yang selanjutnya disingkat RPJMD adalah dokumen perencanaan pembangunan daerah untuk periode 5 (lima) tahun.'),
  (414, 111, 'Pasal 3', 'Ayat (1)', 'Visi Pembangunan Jangka Menengah Daerah Provinsi Kalimantan Selatan Tahun 2021-2026 adalah Kalsel Maju (Kalimantan Selatan Makmur, Sejahtera, dan Berkelanjutan) sebagai Gerbang Ibu Kota Negara.'),
  (415, 111, 'Pasal 5', '', 'RPJMD menjadi pedoman dalam penyusunan Renstra Perangkat Daerah, RKPD, KUA-PPAS, APBD, dan evaluasi penyelenggaraan pemerintahan daerah.');
